#if ANDROID && MATHSOLVER_ANDROID_ARTWORK_PACK
using Android.Content;
using Android.Graphics;
using Android.Graphics.Drawables;
using MathSolver.Services.Artwork;

namespace MathSolver.Platforms.Android;

/// <summary>
/// Android's ImageSource decoders require a bitmap. The pack includes PNG
/// renderings of SVG artwork generated by MAUI at build time.
/// </summary>
public sealed class PackedFileImageSourceService : ImageSourceService,
    IImageSourceService<FileImageSource>
{
    private static readonly SemaphoreSlim Initialization = new(1, 1);
    private static ArtworkProvider? _provider;

    public override async Task<IImageSourceServiceResult<Drawable>?> GetDrawableAsync(
        IImageSource imageSource, Context context, CancellationToken cancellationToken = default)
    {
        cancellationToken.ThrowIfCancellationRequested();
        if (imageSource is not FileImageSource { File: { Length: > 0 } filename })
            return null;

        var provider = await GetProviderAsync(cancellationToken);
        // Android's native ImageSource service accepts raster drawables. Resolve
        // explicit SVG filenames through their build-generated PNG aliases too.
        var rasterName = filename.EndsWith(".svg", StringComparison.OrdinalIgnoreCase)
            ? System.IO.Path.ChangeExtension(filename, ".png")
            : filename;
        var entry = await provider.GetAsync(rasterName, cancellationToken);
        if (entry is null)
            return null;
        if (entry.IsSvg)
            throw new InvalidDataException($"Missing rasterized SVG alias for Android: {filename}");

        cancellationToken.ThrowIfCancellationRequested();
        var bitmap = await Task.Run(
            () => BitmapFactory.DecodeByteArray(entry.Bytes, 0, entry.Bytes.Length),
            cancellationToken);
        if (bitmap is null)
            throw new InvalidDataException($"Cannot decode packed artwork: {entry.Name}");

        // BitmapDrawable takes ownership of its bitmap for display. Do not
        // dispose the bitmap while the Drawable is still in use.
        return new ImageSourceServiceResult(
            new BitmapDrawable(context.Resources, bitmap), true);
    }

    private static async Task<ArtworkProvider> GetProviderAsync(CancellationToken cancellationToken)
    {
        if (_provider is not null)
            return _provider;

        await Initialization.WaitAsync(cancellationToken);
        try
        {
            if (_provider is not null)
                return _provider;

            // APK assets are normally compressed and do not expose a seekable
            // stream. Stage just the archive, once per process, for ZIP lookups.
            // Always refresh the copy on launch to avoid stale same-version APKs.
            var path = System.IO.Path.Combine(FileSystem.CacheDirectory, ArtworkProvider.PackFileName);
            var temporary = path + ".tmp";
            using (var asset = await FileSystem.OpenAppPackageFileAsync(ArtworkProvider.PackFileName))
            await using (var output = new FileStream(temporary, FileMode.Create,
                             FileAccess.Write, FileShare.None, 65536, useAsync: true))
                await asset.CopyToAsync(output, cancellationToken);

            File.Move(temporary, path, true);
            _provider = new ArtworkProvider(path);
            return _provider;
        }
        finally
        {
            Initialization.Release();
        }
    }
}
#endif
